fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Both vectors have the same length as per problem statement.
    // For each index, compare a[i] and b[i] after converting to i32,
    // return true if a[i] > b[i], else false.
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| (x as i32) > (y as i32))
        .collect()
}